import type { DispenseStage, Recipe } from '../types';
import { consumeBeans } from './tenant';

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/** Simulates sending a recipe to the dispenser, reports progress, then deducts the beans from its trays. */
export async function dispenseRecipe(
  dispenserId: string,
  recipe: Recipe,
  onStage: (stage: DispenseStage) => void,
  signal: AbortSignal,
): Promise<void> {
  const stages: DispenseStage[] = ['queued', 'aligning', 'dispensing', 'complete'];
  for (const stage of stages) {
    if (signal.aborted) return;
    if (stage === 'complete') {
      await consumeBeans(
        dispenserId,
        recipe.ingredients.map((i) => ({ flavorId: i.flavor.id, count: i.count })),
      );
    }
    onStage(stage);
    if (stage !== 'complete') await wait(1400);
  }
}
